def delete_notebook_cell(path, cell_id):
    "Delete one notebook cell by stable id."
    path = Path(path)
    with notebook_locks(path):
        nb = read_nb(path)
        idx, cell = find_cell_by_id(nb.cells, cell_id)
        del nb.cells[idx]
